const trigger = $('TelegramTrigger').first().json;
const chatId = String(trigger.message.chat.id);
const text = (trigger.message.text || '').trim();
const items = $input.all();
const row = items[0] && items[0].json && items[0].json.state ? items[0].json : null;
const prevState = row ? row.state : 'idle';
const offered_options = row && row.offered_options ? row.offered_options : null;
const last_generation = row && row.last_generation ? row.last_generation : null;
const hasLast = !!(last_generation && last_generation.promptText);
const t = text.toLowerCase();
const refineSignal = /\b(igual|parecid|semelhante|mesma|mesmo|a mesma|muda|mudar|troca|trocar|altera|alterar|acrescenta|adiciona|mais|menos|sem |com (uma|um|a|o) |em vez|aquela|essa|esta|deixa|p[oõ]e|poe|tira|remove|mant[eé]m)\b/i.test(t);
const startSignal = /^\/start$|^menu$/i.test(t);
const newImgSignal = /(\bcria\w*\b[\s\S]*\bimagem\b)|(\bimagem\b[\s\S]*\b(nova|minha)\b)|(\bnova imagem\b)/i.test(t);
let state;
if (startSignal) state = 'idle';
else if (hasLast && refineSignal) state = 'refine';
else if (newImgSignal) state = 'idle';
else state = prevState;
return [{ json: { chatId, text, state, offered_options, last_generation } }];

const input = $input.first().json;
const num = input.escolha_num;
const offered = input.offered_options || [];
let chosen;
if (num>=1 && num<=3) chosen = offered[num-1];
else if (num===4) chosen = offered[3] || offered[offered.length-1];
if (!chosen) chosen = offered[0] || { prompt:'retrato editorial profissional de advogada, luz suave', mecanismo:'soul_2', aspect:'3:4' };
let promptText;
if (chosen.mecanismo === 'element') promptText = 'Usa a tool Higgsfield generate_image com model nano_banana_pro e o element token da Carolina Felix (id 90ab8942-01f6-4ce3-9bd6-c2def8c7234b), aspect_ratio '+(chosen.aspect||'1:1')+', count 1. Prompt: '+chosen.prompt+'. Responde APENAS com o URL final da imagem, nada mais.';
else promptText = 'Usa a tool Higgsfield generate_image com model soul_2, soul_id 99bf8a15-8d53-45dc-b033-3280841f1454, aspect_ratio '+(chosen.aspect||'3:4')+', quality 2k, count 1. Prompt: '+chosen.prompt+'. Responde APENAS com o URL final da imagem, nada mais.';
return [{ json: { chatId: input.chatId, promptText } }];

const b = $input.first().json.body || $input.first().json;
const ctx = b.context || {};
return [{ json: { chat_id: String(ctx.chat_id || ''), status: b.status || 'error', output: b.output || null, error: b.error || 'sem detalhe', promptText: ctx.promptText || null } }];

const rows = $input.all().map(i => i.json).filter(r => r && r.titulo);
const chatId = $('Route Parse').first().json.chatId;
function pick(arr,n){const a=[...arr];const o=[];while(o.length<n&&a.length){o.push(a.splice(Math.floor(Math.random()*a.length),1)[0]);}return o;}
const byCat = c => rows.filter(r => r.categoria === c);
const chosen = [];
const c = pick(byCat('chiaroscuro'),1)[0]; if(c) chosen.push(c);
const e = pick(byCat('escritorio'),1)[0]; if(e) chosen.push(e);
const x = pick(byCat('exterior'),1)[0]; if(x) chosen.push(x);
while (chosen.length < 3) { const ex = pick(rows.filter(r => r.tipo==='normal' && !chosen.some(k=>k.id===r.id)),1)[0]; if(!ex) break; chosen.push(ex); }
const sur = pick(rows.filter(r=>r.tipo==='surreal'),1)[0] || null;
const nome = {chiaroscuro:'Chiaroscuro', escritorio:'Escritório', exterior:'Exterior', outro:'Editorial'};
const map = r => ({ id:r.id, titulo:r.titulo, prompt:r.prompt, mecanismo:r.mecanismo, aspect:r.aspect, eixos:r.eixos, categoria:r.categoria, rotulo:(nome[r.categoria]||'Editorial') });
const offered = chosen.slice(0,3).map(map);
if (sur) offered.push(map(sur));
return [{ json: { chatId, question: 'Que cenário quer explorar hoje, Carolina?', offered } }];

const raw = ($input.first().json.output || '').trim();
const lines = raw.split('\n').map(l => l.trim()).filter(Boolean);
let mec = 'soul_2';
const mLine = lines.find(l => /^MECANISMO:/i.test(l));
if (mLine) mec = /element/i.test(mLine) ? 'element' : 'soul_2';
let prompt = lines.filter(l => !/^MECANISMO:/i.test(l)).join(' ').trim();
if (!prompt) prompt = 'editorial portrait of an elegant woman lawyer, soft directional window light, tailored blazer, 85mm, shallow depth of field, natural skin texture';
const chatId = String($('TelegramTrigger').first().json.message.chat.id);
let promptText;
if (mec === 'element') {
  promptText = 'Usa a tool Higgsfield generate_image com model nano_banana_pro e o element token da Carolina Felix (id 90ab8942-01f6-4ce3-9bd6-c2def8c7234b), aspect_ratio 3:4, count 1. Prompt: ' + prompt + '. Responde APENAS com o URL final da imagem, nada mais.';
} else {
  promptText = 'Usa a tool Higgsfield generate_image com model soul_2, soul_id 99bf8a15-8d53-45dc-b033-3280841f1454, aspect_ratio 3:4, quality 2k, count 1. Prompt: ' + prompt + '. Responde APENAS com o URL final da imagem, nada mais.';
}
return [{ json: { chatId, promptText } }];

