const trigger = $('TelegramTrigger').first().json;
const chatId = String(trigger.message.chat.id);
const sess = $('Load Session').first() ? ($('Load Session').first().json || {}) : {};
const offered = (sess.offered_options && Array.isArray(sess.offered_options)) ? sess.offered_options : null;
const last_generation = sess.last_generation || null;
const userText = (trigger.message.text || '').trim();
const t = userText.toLowerCase();
// FAST-PATH deterministico: numero isolado 1-4 ou surpreende-me, com menu ativo
const numMatch = t.match(/^([1-4])$/);
const isSurpreende = /^(surpreende-me|surpreenda-me|surpreende|surpreenda|4\.?\s*surpreende.*)$/i.test(t);
if (offered && offered.length > 0 && (numMatch || isSurpreende)) {
  const num = numMatch ? parseInt(numMatch[1]) : 4;
  return [{ json: { chatId, intent:'escolha', escolha_num:num, descricao:null, alteracao:null, reply:null, offered_options: offered, last_generation, userText } }];
}
// senao, usa o Router (Sonnet)
const raw = ($input.first().json.output || '').trim();
let j = {};
try { const s = raw.indexOf('{'), e = raw.lastIndexOf('}'); j = JSON.parse(raw.slice(s, e+1)); } catch(err) { j = { intent:'nova', escolha_num:null, descricao:null, alteracao:null, reply:null }; }
let intent = j.intent || 'nova';
if (intent === 'refino' && !(last_generation && last_generation.promptText)) intent = 'nova';
if (intent === 'escolha' && !(offered && offered.length>0)) intent = 'nova';
return [{ json: { chatId, intent, escolha_num:(j.escolha_num||null), descricao:(j.descricao||null), alteracao:(j.alteracao||null), reply:(j.reply||null), offered_options: offered, last_generation, userText } }];

const g1 = $('Session GET1').first();
const raw = (g1 && g1.json) ? g1.json : {};
return [{ json: {
  state: (raw && raw.state != null) ? raw.state : null,
  offered_options: (raw && raw.offered_options != null) ? raw.offered_options : null,
  last_generation: (raw && raw.last_generation != null) ? raw.last_generation : null
} }];

